insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-213","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In $2\\mathrm{A} + \\mathrm{B} \\to \\mathrm{C}$, if A disappears at $6.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$, C appears at","options":["$3.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$6.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.2 \\times 10^{-2}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.5 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$"],"answer_index":0,"explanation":"Rate $= -\\tfrac12 \\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = +\\mathrm{d}[\\mathrm{C}]/\\mathrm{d}t$, so d[C]/dt is half of 6.0 × 10$^{-3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law"},{"id":"che-ek-214","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Holding [B] fixed, [A] is doubled and the initial rate becomes four times larger. The order with respect to A is","options":["2","1","0","4"],"answer_index":0,"explanation":"rate ∝ [A]$^x$ and $4 = 2^x$ implies $x = 2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law"},{"id":"che-ek-215","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Two runs at the same [B]: [A] = 0.10 M gives rate $1.2 \\times 10^{-4}$; [A] = 0.20 M gives rate $4.8 \\times 10^{-4}$. Order in A and the factor by which rate changes if both [A] and [B] are doubled (order in B is 1) are","options":["2 and a factor of 8","1 and a factor of 4","2 and a factor of 4","0 and a factor of 2"],"answer_index":0,"explanation":"Rate ×4 when [A] ×2 ⇒ order 2 in A. Overall rate $= k[\\mathrm{A}]^2[\\mathrm{B}]$, so doubling both species multiplies the rate by $4 \\times 2 = 8$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"rate-law"},{"id":"che-ek-216","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Rate $= k[\\mathrm{NO}]^2[\\mathrm{O_2}]$ with $k = 1.0 \\times 10^3\\ \\mathrm{L^2\\ mol^{-2}\\ s^{-1}}$. If [NO] = 0.020 M and [O$_2$] = 0.010 M, the rate is","options":["$4.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$4.0 \\times 10^{-6}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$2.0 \\times 10^{-4}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.0 \\times 10^{-2}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$"],"answer_index":0,"explanation":"Rate $= 1.0 \\times 10^3 \\times (0.020)^2 \\times 0.010 = 1.0 \\times 10^3 \\times 4.0 \\times 10^{-6} = 4.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"rate-law"},{"id":"che-ek-217","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The order of a reaction may be zero or fractional, whereas molecularity is","options":["a positive integer (1, 2 or occasionally 3) for an elementary step","always equal to zero","allowed to be negative for unimolecular decays","undefined for every elementary reaction"],"answer_index":0,"explanation":"Order is experimental and can be 0, ½, 1, 2, …. Molecularity counts the molecules in one elementary act and is a small integer.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-218","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molecularity of an elementary step is the","options":["number of species that collide (or decompose) in that single step","sum of the stoichiometric coefficients of the overall equation always","same as the activation energy in kJ","number of products formed"],"answer_index":0,"explanation":"Unimolecular = one species rearranges; bimolecular = two species collide, and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-219","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Overall order is obtained from a rate law rate $= k[\\mathrm{A}]^x[\\mathrm{B}]^y$ as","options":["$x + y$","$x - y$","$x \\times y$","$x / y$"],"answer_index":0,"explanation":"Overall order is the sum of the concentration exponents in the experimental rate law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-220","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A pseudo-first-order reaction is typically a bimolecular process run with","options":["one reactant in large excess, so that its concentration stays nearly constant","both reactants at identical micromolar levels","no solvent present","a catalyst that raises the molecularity to four"],"answer_index":0,"explanation":"Ester hydrolysis in water is the classic case: [H$_2$O] is huge and is absorbed into an effective first-order $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-221","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molecularity is a meaningful idea only for","options":["an elementary step","every complex multi-step reaction as a whole","equilibrium constants","conductivity experiments"],"answer_index":0,"explanation":"A complex reaction is a sequence of elementary steps; it has an order but not a single molecularity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-222","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Decomposition of a single gaseous molecule in one elementary act is described as","options":["unimolecular","bimolecular","zero-order by definition","termolecular only"],"answer_index":0,"explanation":"One reactant species appears in the elementary step, so the molecularity is one.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-223","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A bimolecular elementary reaction involves","options":["a collision between two species (like or unlike)","the simultaneous meeting of four molecules","no collision at all","only a change of solvent polarity"],"answer_index":0,"explanation":"Two particles must encounter each other; the step is first order in each (or second order in one if they are identical).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-224","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ammonia decomposition on a tungsten surface at high pressure is a familiar textbook example of a","options":["zero-order reaction","third-order gas reaction","unimolecular reaction in the gas phase only","reaction with no rate constant"],"answer_index":0,"explanation":"The surface is saturated, so the rate becomes independent of the NH$_3$ pressure: order zero.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity"},{"id":"che-ek-225","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The experimental law rate $= k[\\mathrm{H_2}][\\mathrm{Br_2}]^{1/2}$ has overall order","options":["1.5","2","0.5","1"],"answer_index":0,"explanation":"Exponents add: $1 + 1/2 = 3/2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity"},{"id":"che-ek-226","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Acid-catalysed hydrolysis of methyl acetate in a large excess of water is treated as","options":["pseudo first order in the ester","second order in water","zero order in the ester","third order overall under all conditions"],"answer_index":0,"explanation":"[H$_2$O] is essentially constant, so the observed rate is first order in ester only.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity"},{"id":"che-ek-227","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a reaction that proceeds by several elementary steps, the overall order","options":["need not equal the molecularity of any one step, and is found only by experiment","is always equal to the number of steps","must equal the molecularity of the last step","is undefined if a catalyst is present"],"answer_index":0,"explanation":"Order is a property of the observed rate law. Molecularity belongs to individual steps.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity"},{"id":"che-ek-228","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Termolecular elementary steps are rare because","options":["a simultaneous collision of three molecules is statistically improbable","three molecules can never share electrons","the collision theory forbids $n = 3$ exactly","Faraday's laws prohibit them"],"answer_index":0,"explanation":"Two-body collisions are common; a third body arriving in the same instant is unlikely, so $n = 3$ steps are scarce.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity"},{"id":"che-ek-229","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A rate constant reported as L$^2$ mol$^{-2}$ s$^{-1}$ indicates that the reaction is","options":["third order overall","first order overall","zero order overall","fractional order of ½"],"answer_index":0,"explanation":"Units of $k$ are (conc.)$^{1-n}$ (time)$^{-1}$. L$^2$ mol$^{-2}$ s$^{-1}$ corresponds to $n = 3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity"},{"id":"che-ek-230","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Mechanism: fast equilibrium A + B ⇌ I, followed by slow I → P. The observed order in A and the molecularity of the slow step are","options":["first order in A, and unimolecular","second order in A, and bimolecular","zero order in A, and termolecular","first order in A, and bimolecular"],"answer_index":0,"explanation":"The RDS is unimolecular in I. Substituting [I] = $K[\\mathrm{A}][\\mathrm{B}]$ makes the rate first order in A (and in B).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"order-molecularity"},{"id":"che-ek-231","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integrated first-order rate law is commonly written","options":["$\\ln([\\mathrm{A}]_0/[\\mathrm{A}]) = kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$","$[\\mathrm{A}]^2 = kt$"],"answer_index":0,"explanation":"Integration of $-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = k[\\mathrm{A}]$ yields a linear plot of $\\ln[\\mathrm{A}]$ versus $t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life"},{"id":"che-ek-232","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a zero-order decay the concentration falls linearly according to","options":["$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$\\ln[\\mathrm{A}] = \\ln[\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] = 1/[\\mathrm{A}]_0 + kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 e^{+kt}$"],"answer_index":0,"explanation":"Rate $= k$ (constant), so [A] drops at a constant slope $-k$ until the reactant is exhausted.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-213","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-214","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-215","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-216","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-217","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-218","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-219","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-220","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-221","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-222","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-223","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-224","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-225","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-226","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-227","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-228","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-229","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-230","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-231","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-232","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
